insert into public.tips (id, unit_id, title_en, body_md, status) values
  ('3f75481a-d64a-5253-9be8-a7e4611087e7', 'cf3f5063-9758-597c-a509-2476bd48db2d', 'One thing, two things', 'The verb goes with the *thing*, not with you: **se me cayó la taza**, but **se me cayeron las llaves**; **se me quemó la comida**, **se me quemaron las tostadas**. The *me* stays put — it still happened to you.', 'draft'),
  ('0b9529ef-e03d-56ae-a6c7-238a59a0dca8', 'cf3f5063-9758-597c-a509-2476bd48db2d', 'Se nos, se te', 'When it happened to all of you, the middle word is **nos**: **se nos acabó el café** — *we ran out of coffee*; **se nos rompió la heladera**. To a friend: **¿se te olvidó?**', 'draft'),
  ('22f82d78-a640-5c67-b204-ef2caa3e3182', 'cf3f5063-9758-597c-a509-2476bd48db2d', 'Nobody''s fault', 'That''s the whole point: **no fue mi culpa, se me cayó**. And the excuse every porteño has ready when they''re late: **se me hizo tarde**.', 'draft'),
  ('a46e4610-d990-5c01-ae47-62514d73ca07', 'e27cb9dd-52ff-5eed-8b6b-7f5680e6ae7f', 'While I''m away', 'Going on holiday? Every instruction is a **para que** + what the *other* person does: **te dejo la llave para que entres**, **para que riegues las plantas**, **para que el gato coma**. Two people, so the second verb is subjunctive.', 'draft'),
  ('20a88ba5-1314-583e-ac61-b70812bd1cf5', 'e27cb9dd-52ff-5eed-8b6b-7f5680e6ae7f', 'Sin que', '**Sin que** works the same way: **cerrá la puerta sin que se escape el gato** — *without the cat getting out*. And **antes de que vuelva** — *before I''m back* — hasn''t happened yet.', 'draft'),
  ('4288460e-6410-5750-b081-94888e8c93b5', 'e27cb9dd-52ff-5eed-8b6b-7f5680e6ae7f', 'The stems you know', 'The subjunctive keeps the *yo* stem: *cierro* → **cierres**, *encuentro* → **encuentres**, *riego* → **riegues**. The regular ones just swap the vowel: **entres**, **abras**.', 'draft'),
  ('480771b2-8828-5a35-80e3-1aaf3ecbf53c', '24068540-4ffd-5c2c-86cb-1c89c0f669d6', 'Nunca había…', 'A first time is told with **nunca había** + a participle: **nunca había probado el dulce de leche** — *I''d never tried dulce de leche* (until that day). **Por primera vez** is the other half: **lo probé por primera vez en Buenos Aires**.', 'draft'),
  ('f9ef027b-2738-5b80-a282-75cc7dce9053', '24068540-4ffd-5c2c-86cb-1c89c0f669d6', 'Habíamos', 'With your friends it''s **habíamos**: **ya habíamos terminado cuando llegaste**. The whole set is now *había, habías, habíamos, habían* — and the participle never changes.', 'draft'),
  ('78c655d8-0b95-51e7-988a-2512b7a21517', '24068540-4ffd-5c2c-86cb-1c89c0f669d6', 'Nobody told me', '**No me habían avisado** — *nobody had told me*; **ya lo había llamado** — *I''d already called him*. One more irregular participle: *escribir* → **escrito**.', 'draft'),
  ('ce78c3e8-0bef-5086-a5d6-15b62e2c6fba', '2fd57a10-eb7b-5c55-9f86-fd2716e2ed87', 'Se me, se nos', 'The verb agrees with the thing: **se me cayó la taza**, **se me cayeron las llaves**. The middle word is who it happened to: **se nos acabó el café**.', 'draft'),
  ('cc050468-4d3f-5e25-acaf-76181112b98c', '2fd57a10-eb7b-5c55-9f86-fd2716e2ed87', 'Para que, nunca había', '**Te dejo la llave para que entres** — someone else''s action takes the subjunctive. **Nunca había probado algo así** — one past before another.', 'draft'),
  ('aefc05cf-1bc3-5355-80ac-66c5469787aa', '102a20da-507c-5cab-8d54-b9dc250aebb6', 'Ellos ganaron', 'The other team is *they*: **ganaron**, **perdieron**, **empataron**. Yours is always *we*, from the bar or the sofa: **¡salimos campeones!**', 'draft'),
  ('0543a4d4-e086-5583-a92b-a63cb2d2b3c0', '102a20da-507c-5cab-8d54-b9dc250aebb6', 'Penales', 'A **final** that ends level goes to **penales**: the **arquero atajó** one, somebody **metió** the last, and the whole city is out in the street in the **camiseta**. A great goal is a **golazo**.', 'draft'),
  ('5efffc1b-c968-5b0e-8d8a-6c2df5c0c497', 'd7488f2f-ab30-530b-a0f2-9b26a8cb04ad', 'Anda, andan, anduvo', 'One machine **anda**, two **andan**: **no andan las pilas**. The past is irregular: **ayer anduvo bien** — *it worked fine yesterday*. **Funciona**, **funcionan** mean the same, a bit more formal — the technician''s word.', 'draft'),
  ('c3650361-726d-523a-93eb-fc3114f524cd', 'd7488f2f-ab30-530b-a0f2-9b26a8cb04ad', 'Arreglar', '**¿Me lo podés arreglar?** — *can you fix it for me?* When the **técnico** has been: **lo arregló en cinco minutos**. When he hasn''t, **hacés un reclamo**, and **nos quejamos** all summer.', 'draft'),
  ('abc22894-4d33-582c-ba69-497c6215889e', '35957a48-3965-592b-a5e7-2adfd23edfc0', 'Picking a side', 'All the way with you: **exacto**, **coincido**, **sin duda**. All the way against: **al contrario**. And for the friend who goes too far: **¡no exageres!**', 'draft'),
  ('02a86818-3208-5fb0-9215-3197ea632302', '35957a48-3965-592b-a5e7-2adfd23edfc0', '¿Vos qué opinás?', '**Opinar** is having a view: **¿vos qué opinás?** — *what do you think?*; **yo opino que…**. **Para mí** starts half the sentences at a porteño table: **para mí, depende del tema**.', 'draft'),
  ('d236343e-d2ca-5a28-86e3-f24982d073e2', 'a5ca9719-6dfc-5ebe-8ce3-339422b185b5', 'Ganaron, anduvo', '*They* in the past: **ganaron**, **perdieron**, **empataron**. The machine that let you down: **ayer anduvo**, **hoy no anda**.', 'draft'),
  ('d74aeb37-59af-5591-be40-ad3811e93ce1', 'a5ca9719-6dfc-5ebe-8ce3-339422b185b5', 'Para mí', '**Para mí**, **opino que**, **coincido**, **al contrario** — the whole argument. And the line that ends it: **¡no exageres!**', 'draft'),
  ('e495c6ac-47da-5bcf-a94b-68d0f2de3fab', '747cb533-8260-58bd-a6a1-b2cd7b518fbd', 'El alias', 'Every account has an **alias** — a few words instead of a long number — and paying a friend is **pasame el alias** and **te transfiero**. After: **mandame el comprobante**.', 'draft'),
  ('71a97b7b-6510-5688-b13f-983c17a2d112', '747cb533-8260-58bd-a6a1-b2cd7b518fbd', 'Transfirió', '*Transferir* changes its stem in the past for *él*: **transfirió**. With vos it doesn''t: **¿me transferiste?** Asking for it: **transferime**.', 'draft'),
  ('4b021c65-ffd3-5b07-9dea-dd8581d6491b', '747cb533-8260-58bd-a6a1-b2cd7b518fbd', 'Se me bloqueó', 'The bank has its own accidents: **se me bloqueó la tarjeta**, **se me venció la tarjeta**. Same *se me* as a dropped glass.', 'draft'),
  ('9f0ddf92-7636-5203-a2d2-31863629a9f5', '36036d7c-a216-5b60-a76c-a59bf988487b', 'Me da, me dan', 'Like *gustar*, the scary thing is the subject. One: **me da asco la cucaracha**; more than one: **me dan asco las cucarachas**, **me dan miedo las arañas**.', 'draft'),
  ('c9bc18db-a5bf-5ef4-96f8-705e372ec30f', '36036d7c-a216-5b60-a76c-a59bf988487b', '¿Te dio miedo?', 'In the story it''s the past: **¿te dio miedo?** — **no, me dio risa**. **Me da vergüenza** — *I''m embarrassed* — is built the same way.', 'draft'),
  ('f4296b31-e5fc-50a1-a8e5-b7b5d36a9830', '36036d7c-a216-5b60-a76c-a59bf988487b', 'The summer visitor', 'A hot night, a **cucaracha** in the kitchen, and it **vuela**: **grité**, **salté**, and in the end **la maté** with an **ojota**. Every porteño has this story.', 'draft'),
  ('416011cc-6cbd-510c-882d-29f0a4300a03', '4cba4d7d-a414-57c7-9ed9-cbf8046345e2', 'What people do', 'Same **se** + the *él* form: at an asado **se trae algo** — wine, ice, dessert; **se pone la mesa** while the **asador** handles the **fuego**; **se come** when he says so, **chorizo** first.', 'draft'),
  ('742f77df-09f7-552b-baff-76369529b3b3', '4cba4d7d-a414-57c7-9ed9-cbf8046345e2', 'Un aplauso para el asador', 'At the end **se aplaude al asador**: *¡un aplauso para el asador!* **Se brinda** with everyone at the table. Leaving without saying goodbye to each person? Very **maleducado**.', 'draft'),
  ('605b9c23-3a8a-5a4d-bd8c-b8abb585d7f5', '4092e026-b5b7-5725-9f9e-564fc956c0e4', 'Me dan', '**Me da asco la cucaracha**, **me dan asco las cucarachas** — the verb follows the thing. In the story: **¿te dio miedo?** — **no, me dio risa**.', 'draft'),
  ('651ac73a-308f-5d1a-b438-db93b87e39f5', '4092e026-b5b7-5725-9f9e-564fc956c0e4', 'Se trae, se aplaude', 'What everyone does at an asado: **se trae algo**, **se brinda**, **se aplaude al asador**. **Se** + the *él* form, no subject needed.', 'draft'),
  ('457aa31e-c947-5f00-b748-3212e6826684', '7da0178d-42ee-5e98-aece-77ffbb45dd2d', 'Lo que, the hook', '**No sabés lo que me contaron** — *you won''t believe what I heard* — is how every chisme starts. **Lo que** carries the whole story: **todo lo que pasó**, **lo que me dijo**.', 'draft'),
  ('cba630fb-166d-5c75-b920-75b35d3ba605', '7da0178d-42ee-5e98-aece-77ffbb45dd2d', 'The reactions', '**¡No me digas!** — *no way!*; **¡callate!** — between friends it isn''t rude, it means *you''re kidding!* And by the afternoon **todo el mundo** knows.', 'draft')
